import {sum,divide,unique,match,laborData,monthlyLabor,finance,selectedParts} from './control-model.mjs';
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const number=n=>n==null?'Sin registro':new Intl.NumberFormat('es-PE',{minimumFractionDigits:2,maximumFractionDigits:2}).format(n),money=n=>n==null?'Sin registro':'S/ '+number(n),pct=n=>n==null?'Sin registro':number(n*100)+'%',short=n=>Math.abs(n)>=1e6?(n/1e6).toFixed(1)+' mill.':Math.abs(n)>=1000?(n/1000).toFixed(0)+' mil':Number(n).toFixed(0);
const monthName=m=>new Date(m+'-15T12:00:00').toLocaleDateString('es-PE',{month:'short',year:'numeric'});
const titles=['Resumen ejecutivo','Modelo BIM y avance','Planificación y curva S','Mano de obra programada','Mano de obra · Plan vs. real','Costos y tendencia por hora','Histórico de horas','Materiales','Equipos','Valor ganado','Subcontratos'];
let data,filters={},page=0,tableRows=[],tableColumns=[],generation=0;
const params=new URLSearchParams(location.search);let key=params.get('project')==='a41ecd24-5a8d-4f44-bc3a-53c1416ab5bb'||params.get('project')==='virgen'?'virgen':'simon';
$('#project').value=key;
const cutoff=()=>filters.month?.length?[...filters.month].sort().at(-1):data.cutoff;
const card=(label,value,sub='')=>`<article class="card"><h2>${esc(label)}</h2><div class="value">${esc(value)}</div><small>${esc(sub)}</small></article>`;
const cards=xs=>'<div class="kpis">'+xs.map(x=>card(...x)).join('')+'</div>';
const panel=(title,body,wide=false)=>`<section class="panel ${wide?'wide':''}"><h2>${esc(title)}</h2>${body}</section>`;
const note=t=>`<p class="note">${esc(t)}</p>`;
function chart(rows,series,{line=false,rate=false,field='month',click=true}={}){
 if(!rows.length)return '<div class="empty">No hay datos para esta selección.</div>';
 const w=720,h=300,L=70,R=20,T=25,B=62,pw=w-L-R,ph=h-T-B,vals=rows.flatMap(r=>series.map(s=>r[s.key])).filter(x=>x!=null&&Number.isFinite(x));
 if(!vals.length)return '<div class="empty">Sin registros disponibles.</div>';
 const low=Math.min(0,...vals),high=Math.max(1,...vals),span=high-low,y=v=>T+ph-(v-low)/span*ph,x=i=>L+(i+.5)*pw/rows.length;
 let out='<div class="legend">'+series.map(s=>`<span><i class="dot" style="background:${s.color}"></i>${esc(s.label)}</span>`).join('')+'</div>';
 let svg=`<svg class="chart" viewBox="0 0 ${w} ${h}" role="img" aria-label="${esc(series.map(s=>s.label).join(' y '))}">`;
 for(let i=0;i<=4;i++){let v=low+span*i/4,yy=y(v);svg+=`<path d="M${L} ${yy}H${w-R}" stroke="#e9eef2"/><text x="${L-9}" y="${yy+4}" text-anchor="end">${esc(rate?number(v):short(v))}</text>`;}
 const step=Math.max(1,Math.ceil(rows.length/12));
 rows.forEach((r,i)=>{if(i%step===0||i===rows.length-1){const txt=field==='month'?monthName(r[field]):r[field];svg+=`<text transform="translate(${x(i)},${h-B+19}) rotate(-30)" text-anchor="end">${esc(String(txt).length>23?String(txt).slice(0,22)+'…':txt)}</text>`;}});
 series.forEach((s,j)=>{
  if(line){let d='',open=false;rows.forEach((r,i)=>{if(r[s.key]==null){open=false;return;}d+=(open?'L':'M')+x(i)+' '+y(r[s.key])+' ';open=true;});svg+=`<path d="${d}" fill="none" stroke="${s.color}" stroke-width="1.5"/>`;}
  rows.forEach((r,i)=>{const v=r[s.key];if(v==null)return;const title=`${field==='month'?monthName(r[field]):r[field]} · ${s.label}: ${rate?money(v):number(v)}`;const attr=click&&field==='month'?`data-month="${esc(r[field])}" tabindex="0" role="button" aria-label="Filtrar ${esc(monthName(r[field]))}"`:'';
   if(line){svg+=`<circle cx="${x(i)}" cy="${y(v)}" r="3" fill="${s.color}" ${attr}><title>${esc(title)}</title></circle>`;if(s.labels&&rows.length<=24)svg+=`<text class="label" x="${x(i)}" y="${y(v)-10}" text-anchor="middle">${number(v)}</text>`;}
   else{const bw=Math.min(30,pw/rows.length*.75/series.length),xx=x(i)+(j-series.length/2)*bw;svg+=`<rect x="${xx}" y="${Math.min(y(v),y(0))}" width="${bw-1}" height="${Math.max(1,Math.abs(y(0)-y(v)))}" fill="${s.color}" ${attr}><title>${esc(title)}</title></rect>`;}
  });
 });return out+svg+'</svg>';
}
function table(rows,columns){tableRows=rows;tableColumns=columns;return `<div class="table-tools"><input id="tableSearch" aria-label="Buscar en la tabla" placeholder="Buscar en el detalle…"><button id="csv">Descargar detalle CSV</button><span id="tableCount"></span></div><div class="table-wrap"><table><thead><tr>${columns.map(c=>`<th>${esc(c[1])}</th>`).join('')}</tr></thead><tbody></tbody></table></div><button id="moreRows">Mostrar más filas</button>`;}
function updateTable(limit=100){const body=$('#content tbody');if(!body)return;const q=($('#tableSearch')?.value||'').toLowerCase();const rows=tableRows.filter(r=>tableColumns.some(([k])=>String(r[k]??'').toLowerCase().includes(q)));body.innerHTML=rows.slice(0,limit).map(r=>'<tr>'+tableColumns.map(([k,l,fmt])=>`<td class="${fmt?'num':''}">${esc(fmt?fmt(r[k]):r[k])}</td>`).join('')+'</tr>').join('');$('#tableCount').textContent=Math.min(limit,rows.length)+' de '+rows.length+' filas';$('#moreRows').hidden=rows.length<=limit;$('#moreRows').onclick=()=>updateTable(limit+100);}
function filterKeys(){if([4,5,6].includes(page))return ['month','component','category'];if([3,7,8].includes(page))return ['month','component','specialty','resource','unit'];if(page===10)return [];return ['month','component','specialty'];}
function drawFilters(){const names={month:'Mes de análisis',component:'Componente',specialty:'Especialidad',category:'Categoría de mano de obra',resource:'Recurso',unit:'Unidad'};
 const types={3:'Mano de Obra',7:'Materiales',8:'Equipos'};const rr=data.resources.filter(r=>!types[page]||r.type===types[page]);
 const options={month:unique([...data.schedule.map(r=>r.Fecha.slice(0,7)),...data.labor.map(r=>r.month),...rr.map(r=>r.month)]),component:unique([...data.budget.map(r=>r.Componente),...data.labor.map(r=>r.component)]),specialty:unique(data.parts.map(r=>r.Especialidad)),category:unique([...rr.filter(r=>r.type==='Mano de Obra').map(r=>r.category),...data.labor.map(r=>r.category)]),resource:unique(rr.map(r=>r.resource)),unit:unique(rr.map(r=>r.unit))};
 $('#filters').innerHTML=filterKeys().map(k=>`<details class="filter"><summary><strong>${names[k]}</strong>${filters[k]?.length===1?esc(k==='month'?monthName(filters[k][0]):filters[k][0]):filters[k]?.length?filters[k].length+' seleccionados':'Todos'} ▾</summary><div class="options"><button data-clear="${k}">Todos</button>${options[k].map(x=>`<label><input type="checkbox" data-filter="${k}" value="${esc(x)}" ${filters[k]?.includes(x)?'checked':''}>${esc(k==='month'?monthName(x):x)}</label>`).join('')}</div></details>`).join('')+`<button id="reset">Limpiar filtros</button>`;
 $('#filters').onchange=e=>{if(!e.target.dataset.filter)return;const k=e.target.dataset.filter;const selected=new Set(filters[k]||[]);e.target.checked?selected.add(e.target.value):selected.delete(e.target.value);filters[k]=[...selected];drawFilters();renderContent();};
 $('#filters').onclick=e=>{if(e.target.dataset.clear){filters[e.target.dataset.clear]=[];render();}if(e.target.id==='reset'){filters={};render();}};
}
function monthlyFinancial(){const codes=new Set(selectedParts(data,filters).map(r=>r.Codigo));return unique(data.schedule.filter(r=>codes.has(r.Codigo)).map(r=>r.Fecha.slice(0,7))).map(month=>{const f=finance(data,filters,month);return {month,pv:f.pv,ev:f.ev};});}
function summary(){const f=finance(data,filters,cutoff());const approved=data.progress.find(r=>r.Fecha.slice(0,7)===cutoff());const rows=unique(f.budget.map(r=>r.Componente)).map(component=>{const c=finance(data,{...filters,component:[component]},cutoff());return {component,budget:c.total,real:c.gross,advance:divide(c.ev,c.bac)};});
 return cards([['Presupuesto con IGV',money(f.total),'GG, utilidad e IGV'],['Valorización acumulada',money(f.gross),'Al mes de cierre · con IGV'],['Valorización del mes',money(f.periodGross),'Con IGV'],['Avance acumulado',pct(!filters.component?.length&&!filters.specialty?.length&&approved?approved.Avance:divide(f.gross,f.total)),approved?'Porcentaje aprobado del proyecto':'Valorización / presupuesto'],['SPI',number(f.spi),'EV / PV · costo directo']])+note('Cierre: '+monthName(cutoff())+'. La valorización se presenta con IGV; SPI y valor ganado usan costo directo. Los importes no se mezclan entre proyectos.')+'<div class="grid">'+panel('Presupuesto y valorización acumulada',chart(rows,[{key:'budget',label:'Presupuesto con IGV',color:'#00afa7'},{key:'real',label:'Valorización con IGV',color:'#37474c'}],{field:'component',click:false}))+panel('Avance por componente',chart(rows.map(r=>({...r,advance:(r.advance||0)*100})),[{key:'advance',label:'Avance % · costo directo',color:'#438a9c'}],{field:'component',click:false}))+'</div>'+panel('Detalle del cierre',table(rows,[['component','Componente'],['budget','Presupuesto con IGV',money],['real','Valorización acumulada',money],['advance','Avance costo directo',pct]]));}
function planning(){const f=finance(data,filters,cutoff()),rows=monthlyFinancial();return cards([['PV · plan acumulado',money(f.pv)],['EV · valor ganado',money(f.ev)],['SPI',number(f.spi)],['SV · EV − PV',money(f.sv)]])+panel('Curva S · costo directo',chart(rows,[{key:'pv',label:'Plan acumulado',color:'#1479ae'},{key:'ev',label:'Valor ganado',color:'#b47c15'}],{line:true}))+note('SV expresa diferencia de valor presupuestado, no días de adelanto. EV solo se presenta donde existe un cierre aprobado.')+panel('Detalle mensual',table(rows,[['month','Mes'],['pv','PV acumulado',money],['ev','EV acumulado',money]]));}
function labor(){const a=laborData(data,filters),months=monthlyLabor(data,filters);const categories=unique([...a.plan.map(r=>r.category),...a.real.map(r=>r.category)]).map(category=>({category,...laborData(data,{...filters,category:[category]})}));
 const coverage=data.key==='simon'?'Reales: planillas del Plan de contingencia. Colegio principal: programación disponible; costo real pendiente de identificar.':'Reales sin distribución por componente. Agosto y septiembre se consolidan en septiembre. Al elegir un componente, el real no asignado queda excluido.';
 let out=page===4?cards([['HH planificadas',number(a.planHH)],['HH reales',number(a.realHH)],['Costo planificado',money(a.planCost)],['Costo real',money(a.realCost),'Planilla + bonos registrados'],['S/ por HH · plan',money(a.planRate)],['S/ por HH · real',money(a.realRate)] ]):cards([['Costo real promedio por HH',money(a.realRate),'Costo real total ÷ HH reales'],['HH reales',number(a.realHH)],['Costo real registrado',money(a.realCost)]]);
 const pc={key:'planCost',label:'Costo plan',color:'#00afa7'},rc={key:'realCost',label:'Costo real',color:'#37474c'},ph={key:'planHH',label:'HH plan',color:'#00afa7'},rh={key:'realHH',label:'HH real',color:'#37474c'};
 out+='<div class="grid">';
 if(page===4)out+=panel('Costo mensual programado y real',chart(months,[pc,rc]))+panel('HH por categoría',chart(categories,[ph,rh],{field:'category',click:false}));
 if(page===5)out+=panel('Costo mensual · plan y real',chart(months,[pc,rc]))+panel('Costo por HH · planificado y real',chart(months,[{key:'planRate',label:'Planificado',color:'#1479ae'},{key:'realRate',label:'Real',color:'#b47c15',labels:true}],{line:true,rate:true}));
 if(page===6){let p=0,r=0;const last=months.filter(m=>m.realHH!=null).at(-1)?.month;const accum=months.map(m=>({...m,plan:p+=m.planHH,real:m.month<=last?(r+=m.realHH||0):null}));out+=panel('HH mensuales · plan y real',chart(months,[ph,rh]))+panel('HH acumuladas',chart(accum,[{key:'plan',label:'HH plan acumuladas',color:'#1479ae'},{key:'real',label:'HH reales acumuladas',color:'#b47c15'}],{line:true}));}
 out+='</div>'+note(coverage+' El costo por hora incluye los bonos registrados. Las cargas laborales no registradas siguen pendientes; este indicador no mide productividad sin metrado ejecutado.');
 const rows=page===4?categories:months;out+=panel('Detalle comparativo',table(rows,[[page===4?'category':'month',page===4?'Categoría':'Mes'],['planHH','HH plan',number],['realHH','HH reales',number],['planCost','Costo plan',money],['realCost','Costo real',money],['planRate','S/ por HH plan',money],['realRate','S/ por HH real',money]]));return out;
}
function resources(){const type={3:'Mano de Obra',7:'Materiales',8:'Equipos'}[page];const rows=data.resources.filter(r=>r.type===type&&match(r,filters));const months=unique(rows.map(r=>r.month)).map(month=>({month,cost:sum(rows.filter(r=>r.month===month),'cost')}));const byResource=unique(rows.map(r=>r.resource)).map(resource=>({resource,cost:sum(rows.filter(r=>r.resource===resource),'cost')})).sort((a,b)=>b.cost-a.cost).slice(0,12);const units=unique(rows.map(r=>r.unit));
 return cards([['Costo programado',money(sum(rows,'cost'))],['Cantidad',units.length===1?number(sum(rows,'qty')):'Varias unidades',units.join(' · ')],['Recursos',String(unique(rows.map(r=>r.resource)).length)],['Partidas',String(unique(rows.map(r=>r.code)).length)]])+'<div class="grid">'+panel('Costo programado por mes',chart(months,[{key:'cost',label:'Planificado',color:'#00afa7'}]))+panel('Principales recursos por costo',chart(byResource,[{key:'cost',label:'Planificado',color:'#1479ae'}],{field:'resource',click:false}))+'</div>'+((page===7||page===8)?note('Los gastos reales de gerencia se consultan en Valor ganado. No se asignan artificialmente a una partida o recurso; requieren desglose para esa comparación.'):'')+panel('Detalle por partida y recurso',table(rows.map(r=>({month:r.month,code:r.code,part:r.part,resource:r.resource,unit:r.unit,qty:r.qty,cost:r.cost})),[['month','Mes'],['code','Ítem'],['part','Partida'],['resource','Recurso'],['unit','Unidad'],['qty','Cantidad',number],['cost','Costo',money]]));}
function earned(){const f=finance(data,filters,cutoff());const costs=data.costs.filter(r=>r.Fecha.slice(0,7)<=cutoff());const canCost=!filters.specialty?.length&&(data.key==='virgen'?!filters.component?.length:!filters.component?.length||filters.component.length===1&&filters.component[0]==='II · Plan de contingencia');const ac=canCost?sum(costs.filter(r=>r.Tipo==='Operativo'),'Base'):null;const costEV=data.key==='simon'?finance(data,{...filters,component:['II · Plan de contingencia']},cutoff()).ev:f.ev;const rows=monthlyFinancial().map(r=>({...r,ac:canCost&&r.month<=data.cutoff?sum(data.costs.filter(c=>c.Tipo==='Operativo'&&c.Fecha.slice(0,7)<=r.month),'Base'):null}));
 return cards([['PV · plan acumulado',money(f.pv)],['EV · valor ganado',money(f.ev)],['AC · operativo',money(ac),'Sin IGV · alcance de gerencia'],['BAC · presupuesto directo',money(f.bac)],['SPI',number(f.spi)],['CPI provisional',number(divide(costEV,ac))],['SV · EV − PV',money(f.sv)],['CV provisional',money(ac!=null&&costEV!=null?costEV-ac:null)]])+note(data.key==='simon'?'AC, CPI y CV corresponden al Plan de contingencia; el EV utilizado en CPI/CV se limita a ese componente. Administración y plantel técnico están separados como indirectos.':'AC corresponde al total de obra; no hay distribución por componente o especialidad. Al aplicar estos filtros, AC, CPI y CV quedan sin registro comparable.')+panel('Valor ganado · acumulados a costo directo',chart(rows,[{key:'pv',label:'PV',color:'#1479ae'},{key:'ev',label:'EV',color:'#b47c15'},{key:'ac',label:'AC registrado',color:'#c44d3a'}],{line:true}))+cards([['Gerencia · base sin IGV',money(sum(costs,'Base'))],['IGV registrado',money(sum(costs,'IGV'))],['Gerencia · total con IGV',money(sum(costs,'ConIGV'))]])+panel('Costos reportados a gerencia · no desagregados por filtros',table(costs,[['Fecha','Fecha'],['Area','Área'],['Concepto','Concepto'],['Tipo','Clasificación'],['Base','Sin IGV',money],['IGV','IGV',money],['ConIGV','Con IGV',money]]));}
function subs(){const rows=data.subcontracts.map(r=>({...r,target:r.Expediente*.9,accum:(r.Anterior??r.Septiembre??0)+(r.Octubre||0),remaining:r.Expediente*.9-r.Contratado}));return cards([['Expediente',money(sum(rows,'Expediente'))],['Meta · 90% expediente',money(sum(rows,'target'))],['Contratado',money(sum(rows,'Contratado'))],['Registrado al corte',money(sum(rows,'accum'))]])+note('Acumulado al 31 de octubre de 2026. Meta = 90% del costo presupuestado. Un expediente sin importe no permite evaluar ahorro.')+panel('Comparativo por subcontrato',chart(rows,[{key:'target',label:'Meta 90%',color:'#1479ae'},{key:'Contratado',label:'Contratado',color:'#b47c15'},{key:'accum',label:'Registrado',color:'#37474c'}],{field:'Proveedor',click:false}))+panel('Detalle de subcontratos',table(rows,[['Proveedor','Proveedor'],['Trabajo','Trabajo'],['Expediente','Expediente',money],['target','Meta 90%',money],['Contratado','Contratado',money],['accum','Registrado',money],['remaining','Meta − contratado',money]]));}
function bim(){const parts=selectedParts(data,filters),rows=parts.map(p=>{const close=data.closures.find(c=>c.code===p.Codigo&&c.month===cutoff());return {...p,qty:close?.qty??null,advance:divide(close?.accum,p.Presupuesto)};});return `<div class="model-action"><h2>Modelo actualizado del proyecto</h2><p>Abre el visor 3D para consultar elementos, propiedades, bloques y disciplinas.</p><a href="projects.html?id=${esc(data.project)}">Abrir modelo 3D ↗</a></div>`+note('El modelo permanece en el visor existente. Los metrados de esta tabla provienen del presupuesto y de la valorización; aún no hay selección cruzada entre el 3D y este panel.')+panel('Metrado y avance por partida',table(rows,[['Codigo','Ítem'],['Descripcion','Descripción'],['Unidad','Unidad'],['Metrado','Metrado contractual',number],['qty','Metrado valorizado',number],['advance','Avance costo directo',pct]]));}
function renderContent(){if(!data)return;$('#cutoff').textContent='CIERRE '+monthName(cutoff()).toUpperCase()+(cutoff()<=data.cutoff?' · DATOS AL CORTE':' · PROGRAMACIÓN');$('#pageTitle').textContent=titles[page];$('#status').textContent='Filtros activos: '+filterKeys().filter(k=>filters[k]?.length).length+' · Pulsa una barra o un punto para seleccionar el mes.';$('#content').innerHTML=page===0?summary():page===1?bim():page===2?planning():[3,7,8].includes(page)?resources():[4,5,6].includes(page)?labor():page===9?earned():subs();
 $('#source').textContent='Fuente: datos locales de los informes Power BI, recursos APU y resúmenes de planillas. Datos preparados: '+data.updated.replace('T',' ')+'. Para incorporar nuevos archivos se requiere volver a sincronizar el panel.';
 $('#content').onclick=e=>{const target=e.target.closest('[data-month]');if(target){filters.month=[target.dataset.month];render();}if(e.target.id==='csv')exportCSV();};
 $('#content').onkeydown=e=>{if((e.key==='Enter'||e.key===' ')&&e.target.dataset.month){e.preventDefault();filters.month=[e.target.dataset.month];render();}};
 updateTable();const search=$('#tableSearch');if(search)search.oninput=()=>updateTable();
}
function exportCSV(){if(!tableRows.length)return;const keys=Object.keys(tableRows[0]);const cell=x=>'"'+String(x??'').replace(/^[=+@-]/,"'$&").replaceAll('"','""')+'"';const csv='\ufeff'+[keys,...tableRows.map(r=>keys.map(k=>r[k]))].map(r=>r.map(cell).join(';')).join('\r\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));a.download=data.key+'-'+page+'.csv';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}
function render(){drawFilters();renderContent();$('#pages').innerHTML=titles.map((t,i)=>`<button data-page="${i}" class="${i===page?'active':''}" ${i===page?'aria-current="page"':''}>${String(i+1).padStart(2,'0')} · ${esc(t)}</button>`).join('');}
$('#pages').onclick=e=>{if(e.target.dataset.page!=null){page=Number(e.target.dataset.page);filters=Object.fromEntries(Object.entries(filters).filter(([k])=>filterKeys().includes(k)));render();}};
async function load(){const current=++generation;$('#status').textContent='Cargando datos…';$('#content').innerHTML='';try{const response=await fetch('control-data/'+key+'.json');if(response.status===401){location.href='/login.html?next='+encodeURIComponent('/control.html?project='+key);return;}if(!response.ok)throw Error('Datos pendientes de cargar. Usa Actualizar datos con el archivo del proyecto.');const next=await response.json();if(current!==generation)return;data=next;filters={};$('#projectTitle').textContent=data.title;$('#modelLink').href='projects.html?id='+data.project;history.replaceState(null,'','?project='+key);render();}catch(e){$('#status').textContent=e.message;}}
$('#project').onchange=e=>{key=e.target.value;load();};$('#print').onclick=()=>window.print();load();

$('#dataImport').onchange=async e=>{const files=[...e.target.files];try{for(const file of files){$('#status').textContent='Cargando '+file.name+'…';if(file.size>25*1024*1024)throw Error('Archivo demasiado grande');const text=await file.text(),payload=JSON.parse(text);if(!['simon','virgen'].includes(payload.key))throw Error('Proyecto no válido');const r=await fetch('/control-data/'+payload.key+'.json',{method:'PUT',headers:{'Content-Type':'application/json'},body:text});const result=await r.json();if(!r.ok)throw Error(result.error||'No se pudo guardar');}await load();$('#status').textContent='Datos guardados en el visor para '+files.length+' proyecto(s).';}catch(err){$('#status').textContent=err.message;}finally{e.target.value='';}};
